document = (
    "Machine learning models learn patterns from data.\n\n"
    "They require large datasets and significant compute. Training can take days.\n\n"
    "Once trained, they make predictions on new inputs."
)

def recursive_chunk(text, chunk_size, separators):
    # split on the current separator, recursing into pieces still too large
    if len(text) <= chunk_size or not separators:
        return [text]

    separator = separators[0]
    pieces = text.split(separator)
    chunks = []
    current = ""
    for piece in pieces:
        candidate = current + separator + piece if current else piece
        if len(candidate) <= chunk_size:
            current = candidate
        else:
            if current:
                chunks.append(current)
            # fall back to the next separator down the list
            if len(piece) > chunk_size:
                chunks.extend(recursive_chunk(piece, chunk_size, separators[1:]))
                current = ""
            else:
                current = piece
    if current:
        chunks.append(current)
    return chunks

separators = ["\n\n", ". ", " "]  # paragraph, then sentence, then word breaks
chunks = recursive_chunk(document, chunk_size=80, separators=separators)

print("Recursive chunks:")
for i, chunk in enumerate(chunks):
    print(f"  Chunk {i} ({len(chunk)} chars): {chunk!r}")
